INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000065',1,'APPROVED','PUBLISHED',
'{"objectives":["Use reported speech in Hindi","Use usne kaha ki... to report what someone said","Convert direct speech to indirect"],"explanation":{"intro":"Reported speech (indirect speech) is how we tell others what someone said, thought, or asked. In Hindi, the key construction is usne kaha ki... (he/she said that...).","culturalNote":"Gossip and news-sharing: India has a vibrant oral news culture. Logon ne kaha ki... (people said that...) and usne bataya ki... (he/she told me that...) are daily phrases. WhatsApp groups are the modern version — family groups, colony groups, office groups — everyone shares what someone said. Important: ki (that) in reported speech is mandatory — unlike English where ''that'' can be dropped: He said (that) he was coming vs Hindi: usne kaha ki wo aa raha hai (the ki cannot be dropped). Tense shift: unlike English, Hindi reported speech does NOT require tense backshift — usne kaha ki wo aa raha hai (he said that he IS coming — present tense stays even in reported speech)."},"examples":[{"sentence":"Usne kaha ki wo kal nahi aayega.","english":"He said that he would not come tomorrow."},{"sentence":"Meri maa ne bataya ki khana taiyaar hai.","english":"My mother told me that the food is ready."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can use reported speech to say what others said."}}',
'{"items":[{"word":"usne kaha","translation":"he/she said","transliteration":"usne kaha","pronunciation":"US-ne ka-HA","example":"usne kaha ki"},{"word":"ki","translation":"that (reported speech connector)","transliteration":"ki","pronunciation":"ki","example":"kaha ki"},{"word":"bataya","translation":"told/informed","transliteration":"bataya","pronunciation":"ba-TAA-ya","example":"usne bataya"},{"word":"suna","translation":"heard","transliteration":"suna","pronunciation":"SU-na","example":"maine suna ki"},{"word":"socha","translation":"thought","transliteration":"socha","pronunciation":"SO-cha","example":"usne socha ki"},{"word":"puchha","translation":"asked","transliteration":"puchha","pronunciation":"PUCH-ha","example":"usne puchha ki"}]}',
'{"title":"Usne kaha ki X — He/she said that X (reported speech with ki)","pattern":"Usne kaha ki X = He/she said that X. Usne = he/she (ergative past subject + ne). Kaha = said (past of kehna). Ki = that (mandatory connector). X = the reported content (any clause). No tense backshift in Hindi reported speech — X stays in its natural tense.","explanation":"Reported speech in Hindi: ki is mandatory. The reported clause (after ki) uses the same tense as the original statement — no backshift. Examples: Direct: ''Wo kal aayega'' (He will come tomorrow) → Reported: Usne kaha ki wo kal aayega (He said that he will come tomorrow — not ''would come''). Reporting other verbs: bataya ki (told that), socha ki (thought that), puchha ki (asked whether), suna ki (heard that), likha ki (wrote that). Question reporting: usne puchha ki kya main theek hoon? (He asked whether I am okay).","examples":[{"sentence":"Logon ne kaha ki aaj bandh hai.","english":"People said that there is a strike today."},{"sentence":"Usne puchha ki kya tum aana chahoge.","english":"She asked whether you would like to come."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"In Hindi reported speech, what is the role of ki?","options":["mandatory connector meaning that","optional like English that","tense marker","question word"],"correctAnswer":"mandatory connector meaning that"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"He said that he would not come tomorrow.","options":["Usne kaha ki wo kal nahi aayega.","Usne kaha ki wo aaj nahi aayega.","Usne bataya ki wo kal nahi aayega.","Unho ne kaha ki wo kal nahi aayenge."],"correctAnswer":"Usne kaha ki wo kal nahi aayega."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Meri maa ne bataya ___ khana taiyaar hai.","options":["ki","ko","ke","kar"],"correctAnswer":"ki"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My mother told me that the food is ready.","wordBankItems":["Meri","maa","ne","bataya","ki","khana","taiyaar","hai","."],"correctAnswer":"Meri maa ne bataya ki khana taiyaar hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"socha ki means?","options":["thought that","said that","heard that","asked that"],"correctAnswer":"thought that"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000066',1,'APPROVED','PUBLISHED',
'{"objectives":["Form conditional sentences in Hindi","Use agar...to for if-then conditions","Express real and hypothetical conditions"],"explanation":{"intro":"Conditional sentences express if-then relationships. In Hindi, agar (if) introduces the condition and to (then) introduces the result.","culturalNote":"Conditions in Indian life: agar pariksha paas ki, to graduation party hogi (if you pass the exam, there will be a graduation party). Conditions are deeply embedded in Indian conversational culture — from astrology (agar mangal sahi hua, to shaadi achhi hogi — if Mars is favourable, the wedding will be good) to cricket (agar Kohli out nahi hua, to team jeet sakti hai — if Kohli doesn''t get out, the team can win). The word agar comes from Arabic/Persian (originally: in agar = if that). Hypothetical conditions (past subjunctive) in Hindi: agar main ameer hota, to duniya ghoome hota (if I were rich, I would have traveled the world) — more complex, comes in B1."},"examples":[{"sentence":"Agar kal baarish hui, to hum ghar par rahenge.","english":"If it rains tomorrow, we will stay at home."},{"sentence":"Agar tum mehnat karo, to zaroor safal hoge.","english":"If you work hard, you will surely succeed."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can form real conditional sentences in Hindi using agar...to."}}',
'{"items":[{"word":"agar","translation":"if","transliteration":"agar","pronunciation":"a-GAR","example":"agar baarish"},{"word":"to","translation":"then (result marker)","transliteration":"to","pronunciation":"to","example":"to jaana hoga"},{"word":"warna","translation":"otherwise","transliteration":"warna","pronunciation":"WAR-na","example":"warna mushkil hogi"},{"word":"zaroor","translation":"certainly/definitely","transliteration":"zaroor","pronunciation":"za-ROOR","example":"zaroor hoga"},{"word":"shayad","translation":"perhaps/maybe","transliteration":"shayad","pronunciation":"SHA-yad","example":"shayad aaye"},{"word":"mushkil","translation":"difficult/problem","transliteration":"mushkil","pronunciation":"MUSH-kil","example":"mushkil nahi"}]}',
'{"title":"Agar X, to Y — If X, then Y (real conditional)","pattern":"Agar X, to Y = If X, then Y. Agar = if (condition marker). To = then (result marker — can be omitted in casual speech but always used in writing). X = condition clause (future: karega/karegi/karenge or subjunctive: karo/kare). Y = result clause (future: hoga, milega, etc.). Real conditional = achievable condition about the future.","explanation":"Real conditional in Hindi: agar + condition + to + result. Condition tense: subjunctive (karo/ho/aao) or future (karega/aayega) — both are common. Result tense: usually future (hoga/milega/rahenge). Warna = otherwise (adds the negative result of NOT fulfilling the condition): warna der ho jaayegi (otherwise it will get late). Negative condition: agar nahi kiya (if not done), agar nahi aaye (if they don''t come). Agar can begin the sentence or follow the subject: tum agar jaoge, to main bhi jaaonga (if you go, I will also go).","examples":[{"sentence":"Agar jaldi nahi chale, to train chhoot jaayegi.","english":"If we don''t walk fast, the train will be missed."},{"sentence":"Agar yeh kaam karo, to kuch nahi hoga.","english":"If you do this work, nothing will happen."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"warna means?","options":["otherwise","therefore","although","perhaps"],"correctAnswer":"otherwise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"If it rains tomorrow, we will stay at home.","options":["Agar kal baarish hui, to hum ghar par rahenge.","Agar aaj baarish hui, to hum ghar par rahenge.","Agar kal baarish hui, to hum baahar jayenge.","Agar kal baarish nahi hui, to hum ghar par rahenge."],"correctAnswer":"Agar kal baarish hui, to hum ghar par rahenge."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Agar jaldi nahi chale, to train ___ jaayegi.","options":["chhoot","chhoot ja","chhootega","chhoote"],"correctAnswer":"chhoot"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: If you work hard, you will surely succeed.","wordBankItems":["Agar","tum","mehnat","karo",",","to","zaroor","safal","hoge","."],"correctAnswer":"Agar tum mehnat karo , to zaroor safal hoge ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"shayad means?","options":["perhaps/maybe","certainly","definitely","always"],"correctAnswer":"perhaps/maybe"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000067',1,'APPROVED','PUBLISHED',
'{"objectives":["Express opinions in Hindi","Use mere khayal mein and mere hisaab se","Agree and disagree politely"],"explanation":{"intro":"Expressing opinions and agreeing covers how to give your view, agree with others, and politely disagree in Hindi.","culturalNote":"Opinion culture in India: Indians love debating and sharing opinions — especially about politics (rajneeti), cricket, Bollywood, and food. Opinionated conversation is considered engaging, not confrontational. Key phrases: mere khayal mein (in my opinion — khayal = thought, from Arabic/Urdu khayaal), mere hisaab se (according to my calculation/in my opinion — hisaab = calculation, account), mujhe lagta hai (I think/feel), mere nazariye se (from my point of view — nazariya = viewpoint). Agreeing: bilkul (absolutely), sahi kaha (well said), main aapse sahmat hoon (I agree with you — sahmat = in agreement, from Arabic). Disagreeing: lekin main sochta hoon ki... (but I think that...), is point pe main alag sochta hoon (on this point I think differently)."},"examples":[{"sentence":"Mere khayal mein yeh kaam abhi karna chahiye.","english":"In my opinion this work should be done now."},{"sentence":"Mujhe lagta hai ki yeh decision galat tha.","english":"I think that this decision was wrong."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can express opinions and agree or disagree in Hindi."}}',
'{"items":[{"word":"mere khayal mein","translation":"in my opinion","transliteration":"mere khayal mein","pronunciation":"ME-re KHA-yal mein","example":"mere khayal mein sahi hai"},{"word":"mujhe lagta hai","translation":"I think/feel","transliteration":"mujhe lagta hai","pronunciation":"MU-jhe LAG-ta hai","example":"mujhe lagta hai ki"},{"word":"sahmat","translation":"agree/in agreement","transliteration":"sahmat","pronunciation":"SAH-mat","example":"sahmat hoon"},{"word":"asahmati","translation":"disagreement","transliteration":"asahmati","pronunciation":"a-SAH-ma-ti","example":"asahmati hai"},{"word":"bilkul","translation":"absolutely/exactly","transliteration":"bilkul","pronunciation":"BIL-kul","example":"bilkul sahi"},{"word":"galat","translation":"wrong/incorrect","transliteration":"galat","pronunciation":"ga-LAT","example":"galat nahi"}]}',
'{"title":"Mere khayal mein X — In my opinion X (opinion markers)","pattern":"Mere khayal mein X = In my opinion X. Mujhe lagta hai ki X = I think that X. Mere hisaab se X = According to me X. All three introduce personal opinion. Agreeing: main aapse sahmat hoon (I agree with you). Bilkul sahi (absolutely right). Disagreeing politely: lekin mujhe lagta hai ki... (but I think that...).","explanation":"Opinion construction in Hindi: multiple ways to say ''in my opinion'': (1) mere khayal mein (most common written form), (2) mujhe lagta hai ki (most common spoken form — lit. it seems to me that), (3) mere hisaab se (practical/calculated opinion — lit. by my calculation), (4) mere nazariye se (from my perspective — more formal). Agreement: main sahmat hoon (I agree — sahmat = agreeing). Bilkul (absolutely), haan bilkul (yes absolutely), sahi baat hai (that''s right). Disagreement: nahi, mujhe lagta hai ki... (no, I think that...), is baat se main sahmat nahi (I don''t agree with this point).","examples":[{"sentence":"Mere hisaab se yeh plan sahi hai.","english":"In my opinion this plan is right."},{"sentence":"Is baat se main poori tarah sahmat hoon.","english":"I completely agree with this point."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sahmat means?","options":["agree/in agreement","opinion","correct","definitely"],"correctAnswer":"agree/in agreement"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I think that this decision was wrong.","options":["Mujhe lagta hai ki yeh decision galat tha.","Mujhe lagta hai ki yeh decision sahi tha.","Mere khayal mein yeh decision galat tha.","Mujhe lagta tha ki yeh decision galat hai."],"correctAnswer":"Mujhe lagta hai ki yeh decision galat tha."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Is baat se main poori tarah sahmat ___ .","options":["hoon","hai","ho","hain"],"correctAnswer":"hoon"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In my opinion this plan is right.","wordBankItems":["Mere","hisaab","se","yeh","plan","sahi","hai","."],"correctAnswer":"Mere hisaab se yeh plan sahi hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bilkul means?","options":["absolutely/exactly","almost","sometimes","roughly"],"correctAnswer":"absolutely/exactly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000068',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe changes over time in Hindi","Use pehle X tha, ab Y hai for contrast","Discuss how things have changed"],"explanation":{"intro":"Describing changes over time uses before-now contrast patterns to explain how things were different in the past versus the present.","culturalNote":"Change in modern India: India has undergone massive transformation in recent decades. Economic liberalization (1991) transformed the economy. Technology: pehle koi mobile nahi tha, ab har haath mein smartphone hai (before there were no mobiles, now there is a smartphone in every hand). Infrastructure: pehle sadkein kachchi thin, ab highway hain (before roads were unpaved, now there are highways). Education: pehle ladkiyon ki padhai par dhyan nahi tha, ab bahut badlav aaya hai (before girls'' education was not focused on, now there has been a lot of change). These pehle/ab (before/now) contrasts are extremely common in everyday Hindi conversation — Indians love discussing how much their country has changed. Also: pehle (earlier/before) vs ab (now) vs aage (in the future)."},"examples":[{"sentence":"Pehle yahan ek purana ghar tha, ab yahan ek mall hai.","english":"Before there was an old house here, now there is a mall."},{"sentence":"Pehle log paidal chalte the, ab sab log gaadi chalate hain.","english":"Before people used to walk, now everyone drives a car."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can describe changes over time using pehle...ab contrast in Hindi."}}',
'{"items":[{"word":"pehle","translation":"before/earlier","transliteration":"pehle","pronunciation":"PEH-le","example":"pehle kya tha"},{"word":"ab","translation":"now","transliteration":"ab","pronunciation":"ab","example":"ab kya hai"},{"word":"badlaav","translation":"change/transformation","transliteration":"badlaav","pronunciation":"bad-LAAV","example":"badlaav aana"},{"word":"zamana","translation":"era/times","transliteration":"zamana","pronunciation":"za-MAA-na","example":"purana zamana"},{"word":"dheere-dheere","translation":"gradually/slowly","transliteration":"dheere-dheere","pronunciation":"DHE-re DHE-re","example":"dheere-dheere badalna"},{"word":"aaj kal","translation":"nowadays","transliteration":"aaj kal","pronunciation":"aaj kal","example":"aaj kal ka zamana"}]}',
'{"title":"Pehle X tha, ab Y hai — Before X was, now Y is (temporal contrast)","pattern":"Pehle X tha/thi/the = Before X was. Ab Y hai/hain = Now Y is/are. Pehle = before/earlier (temporal). Ab = now. Tha/thi/the = was (past to be). Hai/hain = is/are (present to be). The contrast highlights change. Extended: pehle X hua karta tha (before X used to happen). Ab X ho raha hai (now X is happening).","explanation":"Change description in Hindi: pehle (before) + past tense → ab (now) + present tense. The contrast makes the change vivid. Gradual change: dheere-dheere badlaav aaya (the change came gradually). Common patterns: pehle X tha, ab X nahi raha (before X was, now X is no more). Pehle log X karte the, ab log Y karte hain (before people used to do X, now people do Y). Context words: aaj kal (nowadays), zamana badal gaya hai (the times have changed), naya zamana (new era).","examples":[{"sentence":"Pehle internet nahi tha, ab sab kuch online hai.","english":"Before there was no internet, now everything is online."},{"sentence":"Dheere-dheere shehar ka chehra badal raha hai.","english":"Gradually the face of the city is changing."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"badlaav means?","options":["change/transformation","improvement","development","progress"],"correctAnswer":"change/transformation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Before there was an old house here, now there is a mall.","options":["Pehle yahan ek purana ghar tha, ab yahan ek mall hai.","Ab yahan ek purana ghar tha, pehle yahan ek mall hai.","Pehle yahan ek mall tha, ab yahan ek purana ghar hai.","Pehle yahan ek purana ghar tha, ab yahan kuch nahi hai."],"correctAnswer":"Pehle yahan ek purana ghar tha, ab yahan ek mall hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dheere-dheere shehar ka chehra badal ___ hai.","options":["raha","rahi","rahe","tha"],"correctAnswer":"raha"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Before there was no internet, now everything is online.","wordBankItems":["Pehle","internet","nahi","tha",",","ab","sab","kuch","online","hai","."],"correctAnswer":"Pehle internet nahi tha , ab sab kuch online hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aaj kal means?","options":["nowadays","today","these days","recently"],"correctAnswer":"nowadays"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000069',1,'APPROVED','PUBLISHED',
'{"objectives":["Make comparisons in Hindi","Use X se zyada Y for more than comparisons","Use X se kam Y for less than comparisons"],"explanation":{"intro":"Making comparisons in Hindi uses the postposition se (from) with zyada (more) or kam (less) to compare two things.","culturalNote":"Comparisons in Indian life: prices (yeh isse sasta hai — this is cheaper than that), quality (yeh woh se accha hai — this is better than that), distance (Mumbai Delhi se zyada door hai — Mumbai is farther than Delhi — debatable depending on starting point!). Superlatives (sabse) are extremely common: sabse accha (the best), sabse bura (the worst), sabse bada (the biggest). Cricket comparisons are endlessly debated: Sachin Tendulkar Kohli se zyada runs banaye hain (Sachin has scored more runs than Kohli). Price comparisons at the market: yeh zyada mehenga hai (this is more expensive), kuch sasta nahi hai kya? (isn''t there something cheaper?). Important: comparison in Hindi uses se (from) not ''than'' — X se zyada = more FROM X = more than X."},"examples":[{"sentence":"Delhi Mumbai se zyada badi hai.","english":"Delhi is bigger than Mumbai."},{"sentence":"Yeh shirt woh se zyada mehenga hai.","english":"This shirt is more expensive than that one."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can make comparisons using se zyada and se kam in Hindi."}}',
'{"items":[{"word":"se zyada","translation":"more than","transliteration":"se zyada","pronunciation":"se ZYAA-da","example":"X se zyada"},{"word":"se kam","translation":"less than","transliteration":"se kam","pronunciation":"se kam","example":"X se kam"},{"word":"sabse","translation":"the most/best (superlative)","transliteration":"sabse","pronunciation":"SAB-se","example":"sabse accha"},{"word":"barabar","translation":"equal/the same","transliteration":"barabar","pronunciation":"ba-RA-bar","example":"dono barabar hain"},{"word":"mehenga","translation":"expensive","transliteration":"mehenga","pronunciation":"me-HEN-ga","example":"mehenga nahi"},{"word":"sasta","translation":"cheap/inexpensive","transliteration":"sasta","pronunciation":"SAS-ta","example":"sasta hai"}]}',
'{"title":"X se zyada/kam Y — X is more/less Y than (comparison with se)","pattern":"X, Y se zyada Z hai = X is more Z than Y. X, Y se kam Z hai = X is less Z than Y. Se = from/than (postposition). Zyada = more. Kam = less. Sabse Z = the most Z (superlative — sabse = from all). Word order: subject first, then the standard of comparison (Y se zyada/kam), then the adjective.","explanation":"Comparison in Hindi: unlike English ''than'', Hindi uses ''se'' (from). Think of it as ''from Y, more Z''. Pattern: [Thing 1] [Thing 2] se zyada [quality] hai. Example: yeh shirt woh se zyada mehenga hai = this shirt, from that one, more expensive is = this shirt is more expensive than that one. Equality: dono barabar hain (both are equal). Superlative: sabse = from all (the most). Sabse accha (the best), sabse bada (the biggest), sabse mushkil (the hardest). Sabse zyada (the most/maximum) vs sabse kam (the least/minimum).","examples":[{"sentence":"Hindi English se zyada mushkil nahi hai.","english":"Hindi is not more difficult than English."},{"sentence":"Mujhe sabse accha khana maa ke haath ka lagta hai.","english":"The best food to me seems to be mother''s home cooking."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"sabse means?","options":["the most/the best (superlative)","very","more","all"],"correctAnswer":"the most/the best (superlative)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Delhi is bigger than Mumbai.","options":["Delhi Mumbai se zyada badi hai.","Mumbai Delhi se zyada badi hai.","Delhi Mumbai se kam badi hai.","Delhi aur Mumbai barabar hain."],"correctAnswer":"Delhi Mumbai se zyada badi hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Hindi English se zyada mushkil ___ hai.","options":["nahi","bahut","thodi","zyada"],"correctAnswer":"nahi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This shirt is more expensive than that one.","wordBankItems":["Yeh","shirt","woh","se","zyada","mehenga","hai","."],"correctAnswer":"Yeh shirt woh se zyada mehenga hai ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sasta means?","options":["cheap/inexpensive","expensive","free","discounted"],"correctAnswer":"cheap/inexpensive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000006a',1,'APPROVED','PUBLISHED',
'{"objectives":["Express wishes and hopes in Hindi","Use kaash X hota for wishes","Use umeed hai ki for hopes"],"explanation":{"intro":"Expressing wishes and hopes covers how to talk about things you wish were true (but aren''t) and things you hope will happen.","culturalNote":"Wishes and hopes in Indian culture: kaash (if only/I wish) is a deeply poetic word from Urdu — frequently used in Bollywood songs and poetry. Kaash main ameer hota (I wish I were rich), kaash wo aata (I wish he would come). Hope phrases: umeed hai (there is hope — umeed from Urdu/Arabic amad = arrival, hope), umeed karna (to hope). Indian optimism: umeed pe duniya qaaim hai (the world stands on hope — famous Urdu expression). Prayers and wishes blend: bhagwan kare ki X ho (may God make X happen). New year wishes: naya saal mubarak ho (happy new year), kaash yeh saal accha ho (I hope/wish this year is good). Dua (prayer/wish — from Arabic): teri dua hai ki... (my prayer/wish is that...)."},"examples":[{"sentence":"Kaash kal baarish na ho.","english":"I wish it wouldn''t rain tomorrow."},{"sentence":"Umeed hai ki woh jaldi theek ho jaaye.","english":"I hope that he/she recovers soon."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can express wishes and hopes in Hindi using kaash and umeed hai ki."}}',
'{"items":[{"word":"kaash","translation":"I wish / if only","transliteration":"kaash","pronunciation":"kaash","example":"kaash ho jaata"},{"word":"umeed","translation":"hope","transliteration":"umeed","pronunciation":"u-MEED","example":"umeed hai"},{"word":"hota/hoti","translation":"would be (subjunctive wish)","transliteration":"hota/hoti","pronunciation":"HO-ta/HO-ti","example":"kaash hota"},{"word":"kaamna","translation":"wish/desire","transliteration":"kaamna","pronunciation":"KAAM-na","example":"meri kaamna hai"},{"word":"praarthana","translation":"prayer","transliteration":"praarthana","pronunciation":"PRAARTHANAA","example":"praarthana karna"},{"word":"shubh","translation":"auspicious/blessed","transliteration":"shubh","pronunciation":"shubh","example":"shubh ho"}]}',
'{"title":"Kaash X hota — I wish X were (counterfactual wish with kaash)","pattern":"Kaash X hota/hoti/hote = I wish X were / If only X were. Kaash = I wish/if only. Hota/hoti/hote = subjunctive past of hona (for wishes about present or future). Umeed hai ki X = I hope that X (more optimistic — possibility exists). Umeed karta hoon ki X = I am hoping that X.","explanation":"Two types of wishful thinking in Hindi: (1) Kaash + subjunctive = counterfactual wish (unlikely or impossible): kaash main pilot hota (I wish I were a pilot — I''m not). (2) Umeed hai ki + clause = hope (possible outcome): umeed hai ki result achha aayega (I hope the result will be good — possible). Kaash with hota/hoti/hote: hota (masculine singular/neuter subjunctive), hoti (feminine singular), hote (plural/formal). Kaash wo yahan hota (I wish he were here). Kaash mujhe pata hota (I wish I had known). Prayer variation: bhagwan kare ki sab theek ho (may God make everything okay — bhagwan kare = may God make it so).","examples":[{"sentence":"Kaash mere paas zyada waqt hota.","english":"I wish I had more time."},{"sentence":"Umeed hai ki kal ka mausam accha hoga.","english":"I hope tomorrow''s weather will be good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kaash means?","options":["I wish / if only","I hope","maybe","probably"],"correctAnswer":"I wish / if only"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I wish it wouldn''t rain tomorrow.","options":["Kaash kal baarish na ho.","Umeed hai ki kal baarish na ho.","Kaash aaj baarish na ho.","Kaash kal baarish ho."],"correctAnswer":"Kaash kal baarish na ho."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Umeed hai ki kal ka mausam accha ___ .","options":["hoga","hai","tha","ho"],"correctAnswer":"hoga"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I wish I had more time.","wordBankItems":["Kaash","mere","paas","zyada","waqt","hota","."],"correctAnswer":"Kaash mere paas zyada waqt hota ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"umeed means?","options":["hope","wish","prayer","desire"],"correctAnswer":"hope"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000006b',1,'APPROVED','PUBLISHED',
'{"objectives":["Communicate by phone and online in Hindi","Use phone conversation openers and closers","Handle SMS, WhatsApp, and email in Hindi"],"explanation":{"intro":"Phone and online communication vocabulary covers how to start and end phone calls, leave voicemails, and communicate online in Hindi.","culturalNote":"Communication in India: WhatsApp is the dominant messaging platform — India is WhatsApp''s largest market with 400M+ users. Phone calls: hai kaun? (who is this?) or haan boliye (yes, speak — answer the phone). Wrong number: galat number hai (wrong number). Network problems: awaaz nahi aa rahi (the voice is not coming through — signal problem). SMS culture: R (aane ke liye ready?) — Hinglish SMS. Email: mostly English in professional settings. Voicemail: koye sandesh chodhiye (leave a message — sandesh = message). Online: video call (video call), WhatsApp call (WhatsApp call), internet bandwidth issues = common. Social media: Instagram (Insta), Facebook (FB), Twitter/X (Twitter). Calling hours: calling after 10pm is considered rude unless close. Miss call (missed call culture — calling and hanging up as a signal)."},"examples":[{"sentence":"Haan, main bol raha hoon — aap kaun bol rahe hain?","english":"Yes, I am speaking — who are you?"},{"sentence":"Mujhe baad mein call karein, main abhi busy hoon.","english":"Please call me later, I am busy right now."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can handle phone calls and online communication in Hindi."}}',
'{"items":[{"word":"haan boliye","translation":"yes please speak (phone answer)","transliteration":"haan boliye","pronunciation":"haan bo-LI-ye","example":"haan boliye"},{"word":"galat number","translation":"wrong number","transliteration":"galat number","pronunciation":"ga-LAT NUM-bar","example":"galat number hai"},{"word":"sandesh","translation":"message","transliteration":"sandesh","pronunciation":"SAN-desh","example":"sandesh chhorna"},{"word":"busy","translation":"busy","transliteration":"busy","pronunciation":"BI-zi","example":"main busy hoon"},{"word":"missed call","translation":"missed call","transliteration":"missed call","pronunciation":"MISSD kawl","example":"missed call aaya"},{"word":"aawaz","translation":"voice/sound","transliteration":"aawaz","pronunciation":"AA-waaz","example":"aawaz nahi aa rahi"}]}',
'{"title":"Phone conversation patterns — answering, asking who, leaving messages","pattern":"Answering: haan boliye (yes please speak) or haan, main X bol raha/rahi hoon (yes, I X am speaking). Asking who: aap kaun bol rahe hain? (who are you speaking?). Not available: abhi unka number dial karein (dial their number now), woh abhi nahi hain (he/she is not here now). Leave a message: koi sandesh dena chahte hain? (do you want to leave a message?). Closing a call: theek hai, chalte hain (okay, goodbye), phir baat karenge (we''ll talk again later).","explanation":"Phone conversation flow in Hindi: (1) Pickup: haan boliye / haan (yes). (2) Identify: main X hoon / X bol raha hoon. (3) Ask for person: kya X hain? (is X there?). (4) Not available: woh abhi nahi hain (they are not here). (5) Message: koi sandesh? (any message?). (6) Will call back: main unhe bataaonga (I will tell them), please callback karein (please call back). (7) Wrong number: maafi chahiye, galat number lag gaya (sorry, wrong number dialled). Online terms: message karo (message me), forward karo (forward it), delete karo (delete it), share karo (share it).","examples":[{"sentence":"Kya Rahul hain? Main unse baat karna chahta hoon.","english":"Is Rahul there? I want to speak with him."},{"sentence":"Unka number mujhe WhatsApp par bhej do.","english":"Send me their number on WhatsApp."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"haan boliye is used for?","options":["answering the phone","saying goodbye","introducing yourself","asking who is calling"],"correctAnswer":"answering the phone"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please call me later, I am busy right now.","options":["Mujhe baad mein call karein, main abhi busy hoon.","Mujhe abhi call karein, main baad mein busy hoon.","Tum baad mein call karo, main abhi busy hoon.","Mujhe baad mein call karein, main abhi theek hoon."],"correctAnswer":"Mujhe baad mein call karein, main abhi busy hoon."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Maafi chahiye, galat ___ lag gaya.","options":["number","awaaz","sandesh","call"],"correctAnswer":"number"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Is Rahul there? I want to speak with him.","wordBankItems":["Kya","Rahul","hain","?","Main","unse","baat","karna","chahta","hoon","."],"correctAnswer":"Kya Rahul hain ? Main unse baat karna chahta hoon ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sandesh means?","options":["message","voice","call","signal"],"correctAnswer":"message"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000006c',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle transactions at banks and post offices in Hindi","Use paisa jama karna for deposits","Understand account and postal vocabulary"],"explanation":{"intro":"At the bank and post office covers the vocabulary and phrases needed for common banking transactions and postal services in India.","culturalNote":"Banking in India: nationalised banks (public sector — SBI = State Bank of India, biggest bank in India, PNB, BOB), private banks (HDFC, ICICI, Axis), cooperative banks. Digital banking: UPI (Unified Payments Interface) has revolutionised payments — PhonePe, Google Pay, Paytm. ATM (ATM). Cheque (cheque). NEFT/RTGS (electronic transfers). Bank documents: passbook (passbook), cheque book (cheque book). Bank terms: khata (account), bachat (savings), mudra (currency), byaj (interest), loan (loan). Post office: India Post (dakghar / post office — largest network in world, 150,000+ offices). Services: registered post (registered dak), speed post, money order (money order — send money to rural areas still popular), savings account at post office. Stamp (tika), envelope (lifaafa), parcel (parcel), address (pata)."},"examples":[{"sentence":"Mujhe is cheque ko jama karwana hai.","english":"I need to deposit this cheque."},{"sentence":"Kripaya mujhe ek registered post form dijiye.","english":"Please give me a registered post form."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can handle basic banking and postal transactions in Hindi."}}',
'{"items":[{"word":"khata","translation":"account","transliteration":"khata","pronunciation":"KHA-ta","example":"bank khata"},{"word":"jama karna","translation":"to deposit","transliteration":"jama karna","pronunciation":"ja-MA KAR-na","example":"paisa jama karna"},{"word":"nikalna","translation":"to withdraw/take out","transliteration":"nikalna","pronunciation":"ni-KAL-na","example":"paisa nikalna"},{"word":"byaj","translation":"interest","transliteration":"byaj","pronunciation":"BYAAJ","example":"byaj mil raha hai"},{"word":"dak","translation":"post/mail","transliteration":"dak","pronunciation":"dak","example":"dak bhejna"},{"word":"tika","translation":"stamp","transliteration":"tika","pronunciation":"TI-ka","example":"tika lagana"}]}',
'{"title":"Bank and post office transaction vocabulary — deposits, withdrawals, postal services","pattern":"Bank transactions: paisa jama karna (to deposit money), paisa nikalna (to withdraw money), khata kholna (to open an account), byaj milna (to receive interest), ATM se paisa nikaalna (to withdraw from ATM). Post office: dak bhejni hai (I need to send mail), speed post karna (to send speed post), parcel bhejna (to send a parcel), registered dak (registered mail).","explanation":"Banking conversation patterns: (1) I want to deposit: mujhe paisa jama karna hai. (2) I want to withdraw: mujhe paisa nikaalna hai. (3) My balance: mera balance kitna hai? (what is my balance?). (4) Open account: main ek naya khata kholna chahta hoon (I want to open a new account). Postal: (1) Speed post: yeh parcel speed post se bhejna hai (I need to send this parcel by speed post). (2) Stamp: ek rupaye ka tika chahiye (I need a one-rupee stamp). (3) Track: mera parcel kahan hai? (where is my parcel?). Digital: UPI se payment karna (to make payment by UPI).","examples":[{"sentence":"Mujhe apne khate mein teen hazaar rupaye jama karne hain.","english":"I need to deposit three thousand rupees in my account."},{"sentence":"Is parcel ko speed post se bhejiye.","english":"Please send this parcel by speed post."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"jama karna means?","options":["to deposit","to withdraw","to transfer","to invest"],"correctAnswer":"to deposit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I need to deposit this cheque.","options":["Mujhe is cheque ko jama karwana hai.","Mujhe is cheque ko nikaalna hai.","Mujhe ek naya cheque chahiye.","Mujhe is cheque ko bhejna hai."],"correctAnswer":"Mujhe is cheque ko jama karwana hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mujhe apne ___ mein teen hazaar rupaye jama karne hain.","options":["khate","paisa","byaj","tika"],"correctAnswer":"khate"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please send this parcel by speed post.","wordBankItems":["Is","parcel","ko","speed","post","se","bhejiye","."],"correctAnswer":"Is parcel ko speed post se bhejiye ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"byaj means?","options":["interest","account","deposit","currency"],"correctAnswer":"interest"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000006d',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe symptoms to a doctor in Hindi","Use mujhe X ho raha hai for symptoms","Understand prescription and medication vocabulary"],"explanation":{"intro":"Health and visiting the doctor covers how to describe illness symptoms, understand a doctor''s questions, and handle prescriptions in Hindi.","culturalNote":"Healthcare in India: government hospitals (sarkari aspataal — free but often crowded), private hospitals (private aspataal — better facilities but expensive), clinics (clinic — private doctor''s clinic). AIIMS (All India Institute of Medical Sciences — top government hospital in Delhi). Jan Aushadhi stores — government-run generic medicine shops (very cheap). Ayurvedic medicine (ayurvedic dava) still popular alongside allopathic (allopathic). Common home remedies: kadha (herbal decoction — ginger + tulsi + black pepper + honey = immunity booster), haldi doodh (turmeric milk), adrak ki chai (ginger tea). Health insurance: increasing adoption. Doctor address: doctor sahib (sir) or simply doctor. Common questions from doctor: kya takleef hai? (what is the problem?), kab se? (since when?), bukhaar hai? (do you have a fever?)."},"examples":[{"sentence":"Doctor sahib, mujhe teen dino se bukhaar aa raha hai.","english":"Doctor, I have been having fever for three days."},{"sentence":"Mujhe pet mein dard ho raha hai aur ulti jaisi lag rahi hai.","english":"I have stomach pain and feel like vomiting."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can describe symptoms and communicate at the doctor''s office in Hindi."}}',
'{"items":[{"word":"bukhaar","translation":"fever","transliteration":"bukhaar","pronunciation":"bu-KHAAR","example":"bukhaar hai"},{"word":"dard","translation":"pain/ache","transliteration":"dard","pronunciation":"dard","example":"dard ho raha hai"},{"word":"khansi","translation":"cough","transliteration":"khansi","pronunciation":"KHAN-si","example":"khansi aa rahi hai"},{"word":"nakseer","translation":"nosebleed","transliteration":"nakseer","pronunciation":"nak-SEER","example":"nakseer aana"},{"word":"dawa","translation":"medicine","transliteration":"dawa","pronunciation":"DA-wa","example":"dawa lena"},{"word":"nuskha","translation":"prescription","transliteration":"nuskha","pronunciation":"NUS-kha","example":"nuskha likhna"}]}',
'{"title":"Mujhe X ho raha hai — I am experiencing X (symptoms with ho raha hai)","pattern":"Mujhe X ho raha hai = I am experiencing X / I have X (ongoing symptom). Mujhe = to me (dative — experiencing subject). X = symptom noun. Ho raha hai = is happening (present continuous of hona). For pain: mujhe X mein dard hai (I have pain in X) or X mein dard ho raha hai. Duration: X dino se (for X days) — mujhe teen dino se bukhaar hai (I''ve had fever for three days).","explanation":"Symptom description in Hindi: dative construction mujhe X ho raha hai for ongoing symptoms. Pain: mujhe sir mein dard hai (I have a headache — lit. to me in head pain is). Nausea: mujhe ulti jaisi lag rahi hai (I feel like vomiting — lit. to me it is feeling like vomit). Weakness: mujhe kamzori mehsoos ho rahi hai (I am feeling weakness). Duration: kab se? (since when?) → X ghante/din/hafte se (since X hours/days/weeks). Doctor''s question: kya X hai? (do you have X?). Describing onset: kal se (since yesterday), subah se (since morning). Medication: dawa kab leni hai? (when should I take medicine?), din mein teen baar (three times a day).","examples":[{"sentence":"Mujhe teen din se neend nahi aa rahi.","english":"I have not been sleeping for three days."},{"sentence":"Kya aapne pahle yeh dawa li hai?","english":"Have you taken this medicine before?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bukhaar means?","options":["fever","cough","headache","cold"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Doctor, I have been having fever for three days.","options":["Doctor sahib, mujhe teen dino se bukhaar aa raha hai.","Doctor sahib, mujhe aaj bukhaar aa raha hai.","Doctor sahib, mujhe ek hafte se bukhaar aa raha hai.","Doctor sahib, mujhe teen dino se khansi aa rahi hai."],"correctAnswer":"Doctor sahib, mujhe teen dino se bukhaar aa raha hai."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mujhe pet mein ___ ho raha hai.","options":["dard","bukhaar","khansi","neend"],"correctAnswer":"dard"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have not been sleeping for three days.","wordBankItems":["Mujhe","teen","din","se","neend","nahi","aa","rahi","."],"correctAnswer":"Mujhe teen din se neend nahi aa rahi ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"nuskha means?","options":["prescription","medicine","treatment","diagnosis"],"correctAnswer":"prescription"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000006e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss renting accommodation in Hindi","Use mujhe rent par ghar chahiye for housing requests","Understand apartment and lease vocabulary"],"explanation":{"intro":"Renting and accommodation covers the vocabulary and conversations needed to find, negotiate, and discuss rented housing in Hindi.","culturalNote":"Renting in India: paying guest (PG = paying guest — room in someone''s home, popular for students and working migrants). 1BHK/2BHK/3BHK (1/2/3 Bedroom Hall Kitchen — standard Indian apartment description — BHK abbreviation universally understood). Rental norms: brokerage (dalali) = 1 month''s rent to the broker, security deposit (zamanat) = 2-3 months'' rent (sometimes up to 10 months!), rent agreement (kiraya namaa) = registered with sub-registrar for legal protection, 11-month lease to avoid registration requirements. Landlord (makan maalik = house owner), tenant (kiraayadaar = rent-person). Maintenance charges (maintenance = extra monthly fee). Society (housing society — gated community). Amenities: generator backup (bijli backup), parking (parking), gym, clubhouse, security (security guard). Brokerage sites: MagicBricks, 99acres, NoBroker (broker-free)."},"examples":[{"sentence":"Mujhe ek 2BHK flat rent par chahiye near metro station.","english":"I need a 2BHK flat on rent near a metro station."},{"sentence":"Kitna kiraya hai aur zamanat kitni lagegi?","english":"How much is the rent and how much security deposit will be charged?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss renting accommodation and understand housing vocabulary in Hindi."}}',
'{"items":[{"word":"kiraya","translation":"rent","transliteration":"kiraya","pronunciation":"ki-RAA-ya","example":"kiraya kitna hai"},{"word":"makan","translation":"house/building","transliteration":"makan","pronunciation":"ma-KAAN","example":"makan rent par"},{"word":"zamanat","translation":"security deposit","transliteration":"zamanat","pronunciation":"za-MA-nat","example":"zamanat dena"},{"word":"makan maalik","translation":"landlord","transliteration":"makan maalik","pronunciation":"ma-KAAN MAA-lik","example":"makan maalik se baat"},{"word":"kiraayadaar","translation":"tenant","transliteration":"kiraayadaar","pronunciation":"ki-RAA-ya-dar","example":"kiraayadaar hoon"},{"word":"agreement","translation":"lease agreement","transliteration":"agreement","pronunciation":"a-GREE-mant","example":"rent agreement karna"}]}',
'{"title":"Mujhe X rent par chahiye — I need X on rent (rental request)","pattern":"Mujhe X rent par chahiye = I need X on rent. Rent par = on rent (par = on/at). Chahiye = need/want (impersonal). Asking rent: kiraya kitna hai? (how much is the rent?). Security: zamanat kitni lagegi? (how much security will be charged?). Availability: kab se milega? (from when will it be available?). Duration: kitne time ke liye? (for how long?).","explanation":"Accommodation search conversation in Hindi: (1) Looking: mujhe ek flat rent par chahiye (I need a flat on rent). (2) Type: 2BHK chahiye (I need a 2BHK). (3) Location: X ke paas (near X). (4) Price inquiry: kitna kiraya hai? and zamanat kitni lagegi?. (5) Amenities: kya parking hai? (is there parking?), bijli backup hai? (is there power backup?), paani ki timing? (water timing?). (6) Agreement: kiraya agreement kab kar sakte hain? (when can we do the rent agreement?). Common terms: furnished (furnished), semi-furnished (semi-furnished), maintenance charges alag se (maintenance charges separate).","examples":[{"sentence":"Kya flat mein furniture hai ya unfurnished hai?","english":"Is there furniture in the flat or is it unfurnished?"},{"sentence":"Main ek hafte mein shifting karna chahta hoon.","english":"I want to shift (move in) within one week."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kiraya means?","options":["rent","deposit","lease","mortgage"],"correctAnswer":"rent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"How much is the rent and how much security deposit will be charged?","options":["Kitna kiraya hai aur zamanat kitni lagegi?","Kitna kiraya hai aur brokerage kitna lagega?","Kitna makan hai aur zamanat kitni lagegi?","Kitna kiraya hai aur zamanat kitni deni hai?"],"correctAnswer":"Kitna kiraya hai aur zamanat kitni lagegi?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mujhe ek 2BHK flat ___ par chahiye.","options":["rent","bech","khareed","kiraya"],"correctAnswer":"rent"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I want to shift within one week.","wordBankItems":["Main","ek","hafte","mein","shifting","karna","chahta","hoon","."],"correctAnswer":"Main ek hafte mein shifting karna chahta hoon ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"zamanat means?","options":["security deposit","rent","brokerage","lease"],"correctAnswer":"security deposit"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

